using System.Collections.Generic;
using UnityEngine;
using UnityEngine.EventSystems;

namespace LittleLeo;

public static class MouseInputUtility
{
	public static List<RaycastResult> GetUIObjectsOverMouse()
	{
		PointerEventData eventData = new PointerEventData(EventSystem.current)
		{
			position = Input.mousePosition
		};
		List<RaycastResult> list = new List<RaycastResult>();
		EventSystem.current.RaycastAll(eventData, list);
		return list;
	}

	public static bool IsPointerOverUIElement()
	{
		return IsPointerOverUIElement(GetUIObjectsOverMouse());
	}

	public static bool IsPointerOverUIElement(List<RaycastResult> eventSystemRaycastResults)
	{
		for (int i = 0; i < eventSystemRaycastResults.Count; i++)
		{
			if (eventSystemRaycastResults[i].gameObject.layer == LayerMask.NameToLayer("UI"))
			{
				return true;
			}
		}
		return false;
	}
}
